import re


class StackUnderflowError(Exception):
    pass


_NUMBER = re.compile(r"-?\d+")


def _is_number(token):
    return _NUMBER.fullmatch(token) is not None


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")
    return [stack.pop() for _ in range(count)]


def _div(a, b):
    quotient = abs(a) // abs(b)
    return quotient if (a >= 0) == (b >= 0) else -quotient


def _expand(tokens, words):
    """Replace user-defined words in a definition body with their (already
    flattened) bodies, so definitions are resolved at definition time."""
    expanded = []
    for token in tokens:
        key = token.lower()
        if key in words:
            expanded.extend(words[key])
        else:
            expanded.append(token)
    return expanded


def evaluate(input_data):
    stack = []
    words = {}

    for line in input_data:
        tokens = line.split()
        i = 0
        while i < len(tokens):
            token = tokens[i]
            key = token.lower()

            if key == ":":
                # : name body... ;
                j = i + 1
                while tokens[j] != ";":
                    j += 1
                name = tokens[i + 1].lower()
                if _is_number(name):
                    raise ValueError("illegal operation")
                words[name] = _expand(tokens[i + 2 : j], words)
                i = j + 1
            elif key in words:
                # Splice the definition body into the token stream; the body
                # is already flattened, so re-process it from position i.
                tokens[i : i + 1] = words[key]
            elif key == "+":
                b, a = _pop(stack, 2)
                stack.append(a + b)
                i += 1
            elif key == "-":
                b, a = _pop(stack, 2)
                stack.append(a - b)
                i += 1
            elif key == "*":
                b, a = _pop(stack, 2)
                stack.append(a * b)
                i += 1
            elif key == "/":
                b, a = _pop(stack, 2)
                if b == 0:
                    raise ZeroDivisionError("divide by zero")
                stack.append(_div(a, b))
                i += 1
            elif key == "dup":
                if not stack:
                    raise StackUnderflowError(
                        "Insufficient number of items in stack"
                    )
                stack.append(stack[-1])
                i += 1
            elif key == "drop":
                _pop(stack, 1)
                i += 1
            elif key == "swap":
                b, a = _pop(stack, 2)
                stack.extend([b, a])
                i += 1
            elif key == "over":
                if len(stack) < 2:
                    raise StackUnderflowError(
                        "Insufficient number of items in stack"
                    )
                stack.append(stack[-2])
                i += 1
            elif _is_number(token):
                stack.append(int(token))
                i += 1
            else:
                raise ValueError("undefined operation")

    return stack

